import"./chunk-VC46IEJQ.js";var e={id:"winterfell",intro:{en:"The great castle of the North: two rings of grey granite wall with a moat between them, raised over hot springs that warm its halls and glass gardens. The novels name many of its buildings but never give a plan, so this scene is a reconstruction.",zh:"\u5317\u5883\u7684\u5DE8\u57CE\uFF1A\u4E24\u9053\u7070\u8272\u82B1\u5C97\u5CA9\u57CE\u5899\u5C42\u5C42\u73AF\u7ED5\uFF0C\u5176\u95F4\u9694\u7740\u62A4\u57CE\u6CB3\uFF1B\u57CE\u4E0B\u6E29\u6CC9\u6D41\u7ECF\uFF0C\u5385\u5802\u4E0E\u73BB\u7483\u82B1\u56ED\u56E0\u6B64\u7EC8\u5E74\u6E29\u6696\u3002\u5C0F\u8BF4\u70B9\u51FA\u4E86\u57CE\u4E2D\u8BB8\u591A\u5EFA\u7B51\uFF0C\u5374\u4ECE\u672A\u7ED9\u51FA\u5E73\u9762\u56FE\uFF0C\u672C\u573A\u666F\u53EA\u662F\u4E00\u79CD\u590D\u539F\u3002"},tour:["walls-and-moat","gates","great-keep","great-hall","first-keep","broken-tower","godswood","hot-springs","glass-gardens","crypts","winter-town"],notes:{en:"From the novels: the double walls and moat, the Great Keep, First Keep, Broken Tower, Great Hall, library tower, godswood, glass gardens, hot-spring heating, the crypts and the winter town. Invented here: every position, building shape and dimension, the gate layout, the street plan and all surface detail.",zh:"\u51FA\u81EA\u5C0F\u8BF4\uFF1A\u53CC\u91CD\u57CE\u5899\u4E0E\u62A4\u57CE\u6CB3\u3001\u4E3B\u5821\u3001\u7B2C\u4E00\u5821\u3001\u65AD\u5854\u3001\u5927\u5385\u3001\u85CF\u4E66\u5854\u3001\u795E\u6728\u6797\u3001\u73BB\u7483\u82B1\u56ED\u3001\u6E29\u6CC9\u4F9B\u6696\u3001\u5730\u4E0B\u5893\u7A96\u4E0E\u51AC\u9547\u3002\u672C\u573A\u666F\u81EA\u884C\u8BBE\u8BA1\uFF1A\u6240\u6709\u4F4D\u7F6E\u3001\u5EFA\u7B51\u9020\u578B\u4E0E\u5C3A\u5BF8\u3001\u57CE\u95E8\u5E03\u5C40\u3001\u8857\u5DF7\u8D70\u5411\u53CA\u4E00\u5207\u8868\u9762\u7EC6\u8282\u3002"},sources:[{ref:"agot",checked:"memory",note:{en:"Winterfell is seen through the Bran, Catelyn and Eddard chapters; recalled, not re-read line by line.",zh:"\u4E34\u51AC\u57CE\u4E3B\u8981\u89C1\u4E8E\u5E03\u5170\u3001\u51EF\u7279\u7433\u4E0E\u827E\u5FB7\u7684\u7AE0\u8282\uFF1B\u51ED\u8BB0\u5FC6\uFF0C\u672A\u9010\u53E5\u91CD\u8BFB\u3002"}},{ref:"acok",checked:"memory",note:{en:"Bran's chapters add the Hunter's Gate and more of the castle's working life; recalled.",zh:"\u5E03\u5170\u7684\u7AE0\u8282\u8865\u5145\u4E86\u730E\u4EBA\u95E8\u53CA\u57CE\u5821\u7684\u65E5\u5E38\u8FD0\u8F6C\uFF1B\u51ED\u8BB0\u5FC6\u3002"}},{ref:"awoiaf",checked:"search-snippet",note:{en:"Web-search summaries of the wiki and the Westeros.org concordance support the wall heights (outer about 80 ft, inner about 100 ft), the east and Hunter's gates, and a covered bridge from the Great Keep to the armoury. The pages themselves could not be fetched.",zh:"\u7EF4\u57FA\u4E0E Westeros.org \u8BCD\u6761\u7D22\u5F15\u7684\u7F51\u7EDC\u641C\u7D22\u6458\u8981\u5370\u8BC1\u4E86\u57CE\u5899\u9AD8\u5EA6\uFF08\u5916\u5899\u7EA6\u516B\u5341\u5C3A\u3001\u5185\u5899\u7EA6\u4E00\u767E\u5C3A\uFF09\u3001\u4E1C\u95E8\u4E0E\u730E\u4EBA\u95E8\uFF0C\u4EE5\u53CA\u4E3B\u5821\u901A\u5F80\u6B66\u5668\u5E93\u7684\u5ECA\u6865\u3002\u9875\u9762\u672C\u8EAB\u65E0\u6CD5\u6293\u53D6\u3002"}}],landmarks:{"walls-and-moat":{name:{en:"Walls and Moat",zh:"\u57CE\u5899\u4E0E\u62A4\u57CE\u6CB3"},desc:{en:"Two rings of granite wall, the inner taller than the outer, with a moat between: attackers who take the outer wall still face open water under the inner wall.",zh:"\u4E24\u5708\u82B1\u5C97\u5CA9\u57CE\u5899\uFF0C\u5185\u5899\u9AD8\u4E8E\u5916\u5899\uFF0C\u4E2D\u95F4\u9694\u7740\u62A4\u57CE\u6CB3\u3002\u653B\u65B9\u5373\u4FBF\u62FF\u4E0B\u5916\u5899\uFF0C\u4ECD\u8981\u5728\u5185\u5899\u4E4B\u4E0B\u6D89\u6C34\u800C\u8FC7\u3002"},tour:{en:"Two granite rings and a moat between them: Winterfell was built to be held.",zh:"\u4E24\u5708\u82B1\u5C97\u5CA9\u57CE\u5899\uFF0C\u4E2D\u5939\u4E00\u9053\u62A4\u57CE\u6CB3\uFF1A\u4E34\u51AC\u57CE\u751F\u6765\u5C31\u662F\u4E3A\u56FA\u5B88\u800C\u5EFA\u3002"},source:{confidence:"high",refs:["agot","awoiaf"],book:{en:"Two concentric walls with a moat between; the inner wall is the taller (about 100 ft against about 80 ft).",zh:"\u4E24\u9053\u540C\u5FC3\u57CE\u5899\uFF0C\u4E2D\u6709\u62A4\u57CE\u6CB3\uFF1B\u5185\u5899\u8F83\u9AD8\uFF08\u7EA6\u4E00\u767E\u5C3A\uFF0C\u5916\u5899\u7EA6\u516B\u5341\u5C3A\uFF09\u3002"},unknown:{en:"Circumference, number of towers and the shape of the rings.",zh:"\u5468\u957F\u3001\u5854\u697C\u6570\u91CF\u53CA\u57CE\u5899\u7684\u5E73\u9762\u5F62\u72B6\u3002"},interpretation:{en:"Slightly irregular oval rings with evenly spaced towers.",zh:"\u57CE\u5899\u753B\u6210\u7565\u4E0D\u89C4\u5219\u7684\u692D\u5706\uFF0C\u5854\u697C\u7B49\u8DDD\u6392\u5217\u3002"}}},gates:{name:{en:"Gates and Drawbridges",zh:"\u57CE\u95E8\u4E0E\u540A\u6865"},desc:{en:"Gatehouses pierce both walls, and drawbridges carry the road across the moat.",zh:"\u57CE\u95E8\u697C\u8D2F\u7A7F\u5185\u5916\u4E24\u9053\u57CE\u5899\uFF0C\u540A\u6865\u5C06\u9053\u8DEF\u67B6\u8FC7\u62A4\u57CE\u6CB3\u3002"},tour:{en:"Every road into Winterfell crosses the moat on a drawbridge.",zh:"\u8FDB\u5165\u4E34\u51AC\u57CE\u7684\u6BCF\u6761\u8DEF\uFF0C\u90FD\u8981\u7ECF\u540A\u6865\u8D8A\u8FC7\u62A4\u57CE\u6CB3\u3002"},source:{confidence:"medium",refs:["agot","acok","awoiaf"],book:{en:"Several gates are mentioned, among them an east gate toward the kingsroad and the Hunter's Gate, which leads out to the wolfswood.",zh:"\u4E66\u4E2D\u63D0\u5230\u591A\u5EA7\u57CE\u95E8\uFF0C\u5176\u4E2D\u6709\u901A\u5411\u56FD\u738B\u5927\u9053\u7684\u4E1C\u95E8\uFF0C\u4EE5\u53CA\u901A\u5F80\u72FC\u6797\u7684\u730E\u4EBA\u95E8\u3002"},unknown:{en:"How many gates there are and exactly where each stands.",zh:"\u57CE\u95E8\u7684\u603B\u6570\u53CA\u5404\u81EA\u7684\u786E\u5207\u4F4D\u7F6E\u3002"},interpretation:{en:"Two matching gatehouses on a north\u2013south axis, unnamed; in the books the main road arrives from the east.",zh:"\u4E24\u5EA7\u5BF9\u79F0\u7684\u57CE\u95E8\u697C\u7F6E\u4E8E\u5357\u5317\u8F74\u7EBF\u4E0A\uFF0C\u672A\u52A0\u547D\u540D\uFF1B\u4E66\u4E2D\u4E3B\u8DEF\u5176\u5B9E\u4ECE\u4E1C\u9762\u800C\u6765\u3002"}}},"great-keep":{name:{en:"Great Keep",zh:"\u4E3B\u5821"},desc:{en:"The main residence of the lords of Winterfell. A bell tower and the rookery rise nearby.",zh:"\u4E34\u51AC\u57CE\u5386\u4EE3\u57CE\u4E3B\u7684\u4E3B\u8981\u5C45\u6240\uFF0C\u9644\u8FD1\u8FD8\u8038\u7ACB\u7740\u949F\u697C\u4E0E\u9E26\u5DE2\u3002"},tour:{en:"The Great Keep is where the Starks live.",zh:"\u4E3B\u5821\u662F\u53F2\u5854\u514B\u4E00\u5BB6\u8D77\u5C45\u4E4B\u6240\u3002"},source:{confidence:"high",refs:["agot","acok"],book:{en:"The Great Keep is the Stark family's residence; a bell tower and a rookery are nearby, and Bran climbs across their roofs.",zh:"\u4E3B\u5821\u662F\u53F2\u5854\u514B\u4E00\u5BB6\u7684\u5C45\u6240\uFF1B\u9644\u8FD1\u6709\u949F\u697C\u4E0E\u9E26\u5DE2\uFF0C\u5E03\u5170\u5E38\u5728\u8FD9\u4E9B\u5C4B\u9876\u95F4\u6500\u722C\u3002"},unknown:{en:"Its floor plan, size and exact relation to the Great Hall.",zh:"\u697C\u5C42\u5E03\u5C40\u3001\u89C4\u6A21\uFF0C\u4EE5\u53CA\u4E0E\u5927\u5385\u7684\u786E\u5207\u5173\u7CFB\u3002"},interpretation:{en:"A broad square keep with four corner turrets and a separate tall bell tower.",zh:"\u5BBD\u9614\u7684\u65B9\u5F62\u4E3B\u5821\uFF0C\u56DB\u89D2\u5404\u6709\u89D2\u697C\uFF0C\u53E6\u7ACB\u4E00\u5EA7\u9AD8\u8038\u7684\u949F\u697C\u3002"}}},"great-hall":{name:{en:"Great Hall",zh:"\u5927\u5385"},desc:{en:"The long hall of feasts and audiences, with a high table, long benches and hearths. A cutaway shows the interior.",zh:"\u4E3E\u884C\u5BB4\u4F1A\u3001\u63A5\u89C1\u81E3\u5C5E\u7684\u957F\u5385\uFF0C\u8BBE\u6709\u4E3B\u684C\u3001\u957F\u51F3\u4E0E\u58C1\u7089\u3002\u53EF\u6253\u5F00\u5256\u9762\u67E5\u770B\u5185\u90E8\u3002"},tour:{en:"Here the household feasts and the lord hears petitions.",zh:"\u57CE\u4E2D\u4E0A\u4E0B\u5728\u6B64\u5BB4\u996E\uFF0C\u57CE\u4E3B\u4E5F\u5728\u6B64\u542C\u53D6\u9648\u60C5\u3002"},source:{confidence:"high",refs:["agot","acok"],book:{en:"A long hall with a high table, trestle tables and benches; the castle's feasts are held here.",zh:"\u8BBE\u6709\u4E3B\u684C\u3001\u957F\u684C\u4E0E\u957F\u51F3\u7684\u957F\u5385\uFF1B\u57CE\u4E2D\u5BB4\u4F1A\u90FD\u5728\u8FD9\u91CC\u4E3E\u884C\u3002"},unknown:{en:"Its dimensions and roof structure.",zh:"\u5C3A\u5BF8\u4E0E\u5C4B\u9876\u7ED3\u6784\u3002"},interpretation:{en:"Timber trusses, stone columns, two hearths and a raised dais at the east end.",zh:"\u6728\u6784\u5C4B\u67B6\u3001\u77F3\u67F1\u3001\u4E24\u5EA7\u58C1\u7089\uFF0C\u4E1C\u7AEF\u8BBE\u9AD8\u53F0\u3002"}}},"first-keep":{name:{en:"First Keep",zh:"\u7B2C\u4E00\u5821"},desc:{en:"The oldest part of the castle: a squat round tower, unused for centuries and crowded with gargoyles.",zh:"\u57CE\u5821\u6700\u53E4\u8001\u7684\u90E8\u5206\uFF1A\u4E00\u5EA7\u77EE\u58A9\u58A9\u7684\u5706\u5854\uFF0C\u8352\u5E9F\u5DF2\u6709\u6570\u767E\u5E74\uFF0C\u6EF4\u6C34\u517D\u5BC6\u5E03\u3002"},tour:{en:"The First Keep is the castle's oldest stone, empty now except for its gargoyles.",zh:"\u7B2C\u4E00\u5821\u662F\u57CE\u4E2D\u6700\u53E4\u8001\u7684\u5EFA\u7B51\uFF0C\u5982\u4ECA\u4EBA\u53BB\u697C\u7A7A\uFF0C\u53EA\u5269\u6EF4\u6C34\u517D\u5B88\u671B\u3002"},source:{confidence:"high",refs:["agot"],book:{en:"Old, round, long abandoned and set about with gargoyles.",zh:"\u53E4\u8001\u7684\u5706\u5854\uFF0C\u4E45\u5DF2\u5E9F\u5F03\uFF0C\u9970\u6EE1\u6EF4\u6C34\u517D\u3002"},unknown:{en:"Whether it still has a roof, and its height.",zh:"\u662F\u5426\u4ECD\u6709\u5C4B\u9876\uFF0C\u4EE5\u53CA\u9AD8\u5EA6\u3002"},interpretation:{en:"A roofless crenellated drum hung with gargoyle spouts.",zh:"\u4E00\u5EA7\u65E0\u9876\u7684\u579B\u53E3\u5706\u5854\uFF0C\u5916\u6302\u6EF4\u6C34\u517D\u3002"}}},"broken-tower":{name:{en:"Broken Tower",zh:"\u65AD\u5854"},desc:{en:"Once the castle's tallest watchtower; lightning set it afire long ago and its top fell in. It was never repaired.",zh:"\u6614\u65E5\u57CE\u4E2D\u6700\u9AD8\u7684\u77AD\u671B\u5854\uFF0C\u5F88\u4E45\u4EE5\u524D\u906D\u96F7\u51FB\u8D77\u706B\uFF0C\u5854\u9876\u584C\u843D\uFF0C\u6B64\u540E\u518D\u672A\u4FEE\u590D\u3002"},tour:{en:"Struck by lightning long ago, the Broken Tower is a ruin, and a temptation to climbers.",zh:"\u65AD\u5854\u65E9\u5E74\u906D\u96F7\u51FB\u800C\u6BC1\uFF0C\u5982\u4ECA\u662F\u4E00\u7247\u5E9F\u589F\uFF0C\u5374\u4E5F\u5F15\u5F97\u7231\u6500\u722C\u7684\u4EBA\u8DC3\u8DC3\u6B32\u8BD5\u3002"},source:{confidence:"high",refs:["agot"],book:{en:"A former watchtower whose upper part collapsed after a lightning fire; Bran climbs it.",zh:"\u539F\u662F\u77AD\u671B\u5854\uFF0C\u96F7\u51FB\u8D77\u706B\u540E\u4E0A\u90E8\u574D\u584C\uFF1B\u5E03\u5170\u66FE\u6500\u4E0A\u6B64\u5854\u3002"},unknown:{en:"Its position within the castle.",zh:"\u5728\u57CE\u5185\u7684\u5177\u4F53\u4F4D\u7F6E\u3002"},interpretation:{en:"A slim square tower snapped off near the top, set in the north-east of the inner ward.",zh:"\u753B\u6210\u8FD1\u9876\u5904\u6298\u65AD\u7684\u7EC6\u9AD8\u65B9\u5854\uFF0C\u7F6E\u4E8E\u5185\u57CE\u4E1C\u5317\u3002"}}},godswood:{name:{en:"Godswood",zh:"\u795E\u6728\u6797"},desc:{en:"Three acres of old forest inside the walls, with a weirwood heart tree beside a still black pool; warm springs steam among the trees.",zh:"\u57CE\u5899\u5185\u4FDD\u7559\u7740\u4E09\u82F1\u4EA9\u539F\u59CB\u68EE\u6797\uFF0C\u9C7C\u6881\u6728\u5FC3\u6811\u65C1\u662F\u4E00\u6F6D\u5E7D\u9ED1\u9759\u6C34\uFF0C\u6797\u95F4\u6E29\u6CC9\u70ED\u6C14\u6C24\u6C32\u3002"},tour:{en:"In the godswood the Starks pray to the old gods before the heart tree.",zh:"\u53F2\u5854\u514B\u5BB6\u4EBA\u5728\u795E\u6728\u6797\u4E2D\uFF0C\u5BF9\u7740\u5FC3\u6811\u5411\u65E7\u795E\u7948\u7977\u3002"},source:{confidence:"high",refs:["agot"],book:{en:"An ancient wood within the walls with a carved heart tree and a black pool; the Starks keep the old gods here.",zh:"\u57CE\u5899\u5185\u7684\u53E4\u6797\uFF0C\u6709\u523B\u7740\u9762\u5B54\u7684\u5FC3\u6811\u548C\u4E00\u6F6D\u9ED1\u6C34\uFF1B\u53F2\u5854\u514B\u5BB6\u65CF\u5728\u6B64\u4F9B\u5949\u65E7\u795E\u3002"},unknown:{en:"Its outline and position relative to the keeps.",zh:"\u6797\u5730\u8F6E\u5ED3\u53CA\u4E0E\u5404\u5821\u7684\u76F8\u5BF9\u4F4D\u7F6E\u3002"},interpretation:{en:"Placed in the north-west, inside the inner wall.",zh:"\u7F6E\u4E8E\u5185\u5899\u4EE5\u5185\u7684\u897F\u5317\u89D2\u3002"}}},"hot-springs":{name:{en:"Hot Springs",zh:"\u6E29\u6CC9"},desc:{en:"Water from hot springs is piped through the walls and fills pools that steam even in deep snow.",zh:"\u6E29\u6CC9\u6C34\u7ECF\u7BA1\u9053\u6D41\u8FC7\u5899\u4F53\uFF0C\u6CE8\u5165\u6C34\u6C60\uFF0C\u5373\u4FBF\u5927\u96EA\u5C01\u57CE\u4E5F\u70ED\u6C14\u84B8\u817E\u3002"},tour:{en:"Winterfell stays warm because of the water beneath it.",zh:"\u4E34\u51AC\u57CE\u4E4B\u6240\u4EE5\u6E29\u6696\uFF0C\u5168\u9760\u5730\u4E0B\u7684\u6CC9\u6C34\u3002"},source:{confidence:"high",refs:["agot","twoiaf"],book:{en:"Hot springs heat the walls and halls and warm the glass gardens; there are hot pools in the godswood.",zh:"\u6E29\u6CC9\u4E3A\u57CE\u5899\u4E0E\u5385\u5802\u4F9B\u6696\uFF0C\u4E5F\u6E29\u6696\u7740\u73BB\u7483\u82B1\u56ED\uFF1B\u795E\u6728\u6797\u4E2D\u6709\u6E29\u6C34\u6C60\u3002"},unknown:{en:"How the pipes run.",zh:"\u7BA1\u9053\u5982\u4F55\u94FA\u8BBE\u3002"},interpretation:{en:"One steaming pool in the godswood stands for the whole system.",zh:"\u4EE5\u795E\u6728\u6797\u4E2D\u4E00\u5904\u5192\u7740\u70ED\u6C14\u7684\u6C34\u6C60\u4EE3\u8868\u6574\u4E2A\u6E29\u6CC9\u7CFB\u7EDF\u3002"}}},"glass-gardens":{name:{en:"Glass Gardens",zh:"\u73BB\u7483\u82B1\u56ED"},desc:{en:"Glasshouses warmed by the springs, where fruit and vegetables grow through the northern winter.",zh:"\u501F\u6E29\u6CC9\u4FDD\u6696\u7684\u73BB\u7483\u6E29\u5BA4\uFF0C\u5317\u5883\u5BD2\u51AC\u91CC\u7167\u6837\u80FD\u79CD\u51FA\u852C\u679C\u3002"},tour:{en:"Under glass roofs, green things grow while snow falls outside.",zh:"\u73BB\u7483\u5C4B\u9876\u4E0B\u7EFF\u610F\u76CE\u7136\uFF0C\u5C4B\u5916\u5374\u662F\u6F2B\u5929\u98DE\u96EA\u3002"},source:{confidence:"high",refs:["agot"],book:{en:"The castle has glass gardens warmed by the hot springs.",zh:"\u57CE\u4E2D\u6709\u9760\u6E29\u6CC9\u4FDD\u6696\u7684\u73BB\u7483\u82B1\u56ED\u3002"},unknown:{en:"Their position and form.",zh:"\u4F4D\u7F6E\u4E0E\u5F62\u5236\u3002"},interpretation:{en:"Three glasshouses beside the Great Keep.",zh:"\u4E3B\u5821\u65C1\u7684\u4E09\u5EA7\u73BB\u7483\u6E29\u5BA4\u3002"}}},crypts:{name:{en:"Crypts",zh:"\u5730\u4E0B\u5893\u7A96"},desc:{en:"Beneath the castle, a long line of stone Starks sit on their tombs with iron swords across their knees. A cutaway shows the vaulted gallery.",zh:"\u57CE\u5821\u5730\u4E0B\uFF0C\u4E00\u5C0A\u5C0A\u53F2\u5854\u514B\u77F3\u50CF\u7AEF\u5750\u5893\u524D\uFF0C\u819D\u4E0A\u6A2A\u653E\u94C1\u5251\u3002\u53EF\u6253\u5F00\u5256\u9762\u67E5\u770B\u62F1\u9876\u957F\u5ECA\u3002"},tour:{en:"Below the castle, the Kings of Winter and the lords after them sit in stone.",zh:"\u57CE\u5821\u4E4B\u4E0B\uFF0C\u5386\u4EE3\u51AC\u5883\u4E4B\u738B\u4E0E\u540E\u6765\u7684\u57CE\u4E3B\u5316\u4F5C\u77F3\u50CF\u9759\u5750\u3002"},source:{confidence:"high",refs:["agot"],book:{en:"The crypts hold the Stark dead, each with a stone likeness and an iron sword; stone direwolves lie at their feet.",zh:"\u5893\u7A96\u5B89\u846C\u7740\u53F2\u5854\u514B\u5148\u4EBA\uFF0C\u6BCF\u5EA7\u5893\u524D\u90FD\u6709\u77F3\u50CF\u4E0E\u94C1\u5251\uFF0C\u811A\u8FB9\u5367\u7740\u77F3\u96D5\u51B0\u539F\u72FC\u3002"},unknown:{en:"Where the entrance is and how the deeper levels are laid out.",zh:"\u5165\u53E3\u4F4D\u7F6E\uFF0C\u4EE5\u53CA\u66F4\u6DF1\u5C42\u7684\u683C\u5C40\u3002"},interpretation:{en:"The entrance is placed near the Great Keep; one straight vaulted gallery stands for the whole.",zh:"\u5165\u53E3\u8BBE\u5728\u4E3B\u5821\u9644\u8FD1\uFF1B\u4EE5\u4E00\u6761\u7B14\u76F4\u7684\u62F1\u9876\u957F\u5ECA\u4EE3\u8868\u5168\u8C8C\u3002"}}},"library-tower":{name:{en:"Library Tower",zh:"\u85CF\u4E66\u5854"},desc:{en:"The tower that houses Winterfell's library, with a stair winding round its outside.",zh:"\u4E34\u51AC\u57CE\u85CF\u4E66\u6240\u5728\u7684\u5854\u697C\uFF0C\u5854\u5916\u6709\u4E00\u9053\u76D8\u65CB\u800C\u4E0A\u7684\u77F3\u9636\u3002"},tour:{en:"Winterfell keeps its books in a tower of their own.",zh:"\u4E34\u51AC\u57CE\u7684\u85CF\u4E66\uFF0C\u5355\u72EC\u5B58\u653E\u5728\u4E00\u5EA7\u5854\u91CC\u3002"},source:{confidence:"medium",refs:["agot","awoiaf"],book:{en:"A library tower is named in the first novel, where a fire breaks out in it.",zh:"\u7B2C\u4E00\u90E8\u5C0F\u8BF4\u4E2D\u63D0\u5230\u85CF\u4E66\u5854\uFF0C\u5854\u91CC\u66FE\u8D77\u8FC7\u4E00\u573A\u706B\u3002"},unknown:{en:"Its location, size and what it connects to.",zh:"\u4F4D\u7F6E\u3001\u89C4\u6A21\u53CA\u4E0E\u54EA\u4E9B\u5EFA\u7B51\u76F8\u8FDE\u3002"},interpretation:{en:"Set on the west side of the inner ward. The covered gallery to the armoury is invented; the books' covered bridge runs from the Great Keep to the armoury.",zh:"\u7F6E\u4E8E\u5185\u57CE\u897F\u4FA7\u3002\u901A\u5F80\u6B66\u5668\u5E93\u7684\u5ECA\u9053\u4E3A\u672C\u573A\u666F\u865A\u6784\uFF1B\u4E66\u4E2D\u7684\u5ECA\u6865\u8FDE\u63A5\u7684\u662F\u4E3B\u5821\u4E0E\u6B66\u5668\u5E93\u3002"}}},stables:{name:{en:"Stables",zh:"\u9A6C\u53A9"},desc:{en:"Long working stables, with the kennels close by.",zh:"\u72ED\u957F\u7684\u9A6C\u53A9\uFF0C\u72AC\u820D\u5C31\u5728\u8FD1\u65C1\u3002"},tour:{en:"Everyday Winterfell: stables, kennels and smoke.",zh:"\u5BFB\u5E38\u65E5\u5B50\u91CC\u7684\u4E34\u51AC\u57CE\uFF1A\u9A6C\u53A9\u3001\u72AC\u820D\u4E0E\u708A\u70DF\u3002"},source:{confidence:"medium",refs:["agot"],book:{en:"Stables and kennels are part of the castle's working yards.",zh:"\u9A6C\u53A9\u4E0E\u72AC\u820D\u662F\u57CE\u4E2D\u65E5\u5E38\u8BBE\u65BD\u7684\u4E00\u90E8\u5206\u3002"},unknown:{en:"Their positions.",zh:"\u5177\u4F53\u4F4D\u7F6E\u3002"},interpretation:{en:"South side of the inner ward.",zh:"\u7F6E\u4E8E\u5185\u57CE\u5357\u4FA7\u3002"}}},kitchens:{name:{en:"Kitchens",zh:"\u53A8\u623F"},desc:{en:"A busy service block of chimneys and bread ovens that feeds the household.",zh:"\u70DF\u56F1\u6797\u7ACB\u3001\u9762\u5305\u7089\u4E0D\u7184\u7684\u5FD9\u788C\u53A8\u623F\uFF0C\u4F9B\u517B\u5168\u57CE\u4E0A\u4E0B\u3002"},tour:{en:"The kitchen chimneys smoke day and night.",zh:"\u53A8\u623F\u7684\u70DF\u56F1\u663C\u591C\u5192\u70DF\u3002"},source:{confidence:"medium",refs:["agot"],book:{en:"The castle has kitchens; Bran knows their roofs from his climbing.",zh:"\u57CE\u4E2D\u6709\u53A8\u623F\uFF1B\u5E03\u5170\u6500\u722C\u65F6\u5BF9\u5176\u5C4B\u9876\u4E86\u5982\u6307\u638C\u3002"},unknown:{en:"Position and form.",zh:"\u4F4D\u7F6E\u4E0E\u5F62\u5236\u3002"},interpretation:{en:"A service building in the south-east.",zh:"\u7F6E\u4E8E\u4E1C\u5357\u7684\u6742\u5F79\u5EFA\u7B51\u3002"}}},forge:{name:{en:"Forge",zh:"\u94C1\u5320\u94FA"},desc:{en:"The castle smithy, where the armourer keeps the household in steel.",zh:"\u57CE\u5821\u7684\u94C1\u5320\u94FA\uFF0C\u519B\u68B0\u5320\u5728\u6B64\u4E3A\u5168\u57CE\u6253\u9020\u5175\u7532\u3002"},tour:{en:"The smith's hammer serves the whole garrison.",zh:"\u94C1\u5320\u7684\u9524\u58F0\uFF0C\u4E3A\u5168\u57CE\u5B88\u519B\u800C\u54CD\u3002"},source:{confidence:"medium",refs:["agot"],book:{en:"Winterfell has a forge and a master armourer.",zh:"\u4E34\u51AC\u57CE\u6709\u94C1\u5320\u94FA\uFF0C\u4E5F\u6709\u4E00\u4F4D\u519B\u68B0\u5E08\u5085\u3002"},unknown:{en:"Its position.",zh:"\u5177\u4F53\u4F4D\u7F6E\u3002"},interpretation:{en:"East side of the inner ward.",zh:"\u7F6E\u4E8E\u5185\u57CE\u4E1C\u4FA7\u3002"}}},"training-yard":{name:{en:"Training Yard",zh:"\u6821\u573A"},desc:{en:"An open yard with practice swords, straw dummies and archery butts.",zh:"\u4E00\u7247\u5F00\u9614\u7684\u9662\u5B50\uFF0C\u5907\u6709\u7EC3\u4E60\u5251\u3001\u8349\u4EBA\u4E0E\u7BAD\u9776\u3002"},tour:{en:"Boys and men learn sword and bow here.",zh:"\u5C11\u5E74\u4E0E\u58EB\u5175\u5728\u8FD9\u91CC\u4E60\u5251\u7EC3\u7BAD\u3002"},source:{confidence:"high",refs:["agot"],book:{en:"A yard where the Stark children and the garrison train at arms.",zh:"\u53F2\u5854\u514B\u5BB6\u7684\u5B69\u5B50\u4E0E\u5B88\u519B\u5728\u6B64\u64CD\u7EC3\u6B66\u827A\u3002"},unknown:{en:"Its position.",zh:"\u5177\u4F53\u4F4D\u7F6E\u3002"},interpretation:{en:"South-west of the Great Keep.",zh:"\u7F6E\u4E8E\u4E3B\u5821\u897F\u5357\u3002"}}},"winter-town":{name:{en:"Winter Town",zh:"\u51AC\u9547"},desc:{en:"A town outside the walls, half empty in summer, where people from across the North shelter in winter.",zh:"\u57CE\u5899\u5916\u7684\u5C0F\u9547\uFF0C\u590F\u65E5\u91CC\u534A\u57CE\u7A7A\u7F6E\uFF0C\u5165\u51AC\u540E\u5317\u5883\u5404\u5730\u7684\u4EBA\u7EB7\u7EB7\u6765\u6B64\u907F\u5BD2\u3002"},tour:{en:"In winter the town fills with families seeking the castle's protection.",zh:"\u4E00\u5230\u51AC\u5929\uFF0C\u6295\u5954\u57CE\u5821\u5E87\u62A4\u7684\u4EBA\u5BB6\u4FBF\u628A\u51AC\u9547\u4F4F\u5F97\u6EE1\u6EE1\u5F53\u5F53\u3002"},source:{confidence:"medium",refs:["agot","twoiaf"],book:{en:"The winter town lies outside the walls and fills up when winter comes.",zh:"\u51AC\u9547\u4F4D\u4E8E\u57CE\u5916\uFF0C\u6BCF\u9022\u51AC\u5B63\u4FBF\u4EBA\u6EE1\u4E3A\u60A3\u3002"},unknown:{en:"Its layout, size and street names.",zh:"\u5E03\u5C40\u3001\u89C4\u6A21\u4E0E\u8857\u540D\u3002"},interpretation:{en:"Houses strung along one cobbled road beyond the south gate.",zh:"\u5357\u95E8\u5916\u4E00\u6761\u9E45\u5375\u77F3\u8DEF\uFF0C\u4E24\u4FA7\u6392\u5F00\u623F\u5C4B\u3002"}}}}};export{e as default};
